    private bool HandleWorkspaceShortcut(Key key,ModifierKeys modifiers)
    {
        if(modifiers!=ModifierKeys.Control)return false;
        switch(key)
        {
            case Key.K:if(navigationColumn.Width.Value==0)ToggleNavigation();historySearch.Focus();historySearch.SelectAll();return true;
            case Key.N when !busy:NewConversation();ShowChat();prompt.Focus();return true;
            case Key.B:ToggleNavigation();return true;
            case Key.J:ToggleInspector();return true;
            case Key.L:ShowChat();prompt.Focus();return true;
            default:return false;
        }
    }
