    private GridSplitter Splitter(int column){var splitter=new GridSplitter{Width=1,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Stretch,Background=Brush("#222935"),ResizeDirection=GridResizeDirection.Columns,ResizeBehavior=GridResizeBehavior.PreviousAndNext,Focusable=true};Grid.SetColumn(splitter,column);workspaceGrid.Children.Add(splitter);System.Windows.Automation.AutomationProperties.SetName(splitter,column==1?"Resize chats":"Resize workspace");return splitter;}
    private void ToggleNavigation(){var visible=navigationColumn.Width.Value!=0;navigationColumn.MinWidth=visible?0:180;navigationColumn.Width=new GridLength(visible?0:220);workspaceGrid.Children.OfType<DockPanel>().First(p=>Grid.GetColumn(p)==0).Visibility=visible?Visibility.Collapsed:Visibility.Visible;if(navigationSplitter!=null)navigationSplitter.Visibility=visible?Visibility.Collapsed:Visibility.Visible;}
    private void ToggleInspector(){if(AgentSurfaceActive){OpenAgentWorkbench();return;}var visible=inspectorColumn.Width.Value!=0;inspectorColumn.MinWidth=visible?0:220;inspectorColumn.Width=new GridLength(visible?0:270);workspaceGrid.Children.OfType<DockPanel>().First(p=>Grid.GetColumn(p)==4).Visibility=visible?Visibility.Collapsed:Visibility.Visible;if(inspectorSplitter!=null)inspectorSplitter.Visibility=visible?Visibility.Collapsed:Visibility.Visible;}
    private void RememberContext()=>chatContexts[conversation.Id]=(files.ToArray(),webSources.ToArray());
    private void RestoreContext(){RefreshImageTray();files.Clear();webSources.Clear();if(chatContexts.TryGetValue(conversation.Id,out var saved)){files.AddRange(saved.Files);webSources.AddRange(saved.Sources);}}
    private void SelectInspector(string name){rightPaneMode="Workspace";rightPaneBody.Content=workspaceInspector;inspectorContent.Content=name switch{"Sources"=>sourcesInspector,"Task"=>briefInspector,_=>filesInspector};foreach(var pair in workspaceTabs){pair.Value.Background=Brush(pair.Key==name?"#232D43":"#101318");pair.Value.Foreground=Brush(pair.Key==name?"#B8CCFF":"#98A4B7");}}
    private void OpenResearch(){SelectInspector("Sources");var window=new ResearchWindow{Owner=this};if(researchTestAction!=null)window.Loaded+=(_,_)=>researchTestAction(window);if(window.ShowDialog()==true){foreach(var source in window.Sources){if(webSources.Count==6)break;if(webSources.All(s=>s.Url!=source.Url))webSources.Add(source);}UpdateContext();status.Text=$"Included {webSources.Count} source excerpts • review them before sending.";}}
    private void ReviewSources(){var w=new Window{Title="Included web sources",Width=850,Height=550,Owner=this,WindowStartupLocation=WindowStartupLocation.CenterOwner};DarkTheme.Apply(w);DarkTheme.Wrap(w,new TextBox{Text=webSources.Count==0?"No web sources included.":WebResearch.Format(webSources),IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Margin=new Thickness(18)});w.ShowDialog();}
    private void RefreshInspector(){contextSummary.Text=$"{files.Count} source files · {files.Sum(f=>Encoding.UTF8.GetByteCount(f.Content)):N0} bytes\n{webSources.Count} included web sources";contextSummary.ToolTip="Only included source files and excerpts enter model context. Saved draft paths are not automatically included.";sourceRows.Children.Clear();foreach(var s in webSources){sourceRows.Children.Add(new TextBlock{Text=s.Title,FontWeight=FontWeights.SemiBold,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,8,0,4)});sourceRows.Children.Add(new TextBlock{Text=s.Url,Foreground=Brush("#83A3FF"),FontSize=11,TextWrapping=TextWrapping.Wrap,ToolTip=s.Excerpt});}if(webSources.Count==0)sourceRows.Children.Add(new TextBlock{Text="No sources included yet.",Foreground=Brush("#7F8A9D"),TextWrapping=TextWrapping.Wrap});}
    private void FlushBrief(){briefSaveTimer.Stop();if(briefOwner==null)return;try{if(briefDirty||briefOwner.TaskBrief.Length>0||briefOwner.Messages.Count>0)store.Save(briefOwner);briefDirty=false;briefSaved.Text="Saved locally with this chat";}catch(Exception e) when(e is IOException or UnauthorizedAccessException){briefSaved.Text="Could not save brief. Try Save brief again.";status.Text="Task brief save failed: "+e.Message;}}
    private void SyncConversationUi(){syncingUi=true;try{briefOwner=conversation;briefEditor.Text=conversation.TaskBrief;responseStyle.SelectedItem=conversation.ResponseStyle is "Ask" or "Plan"?conversation.ResponseStyle:"Build";cliMode.SelectedIndex=conversation.AutoCliFallback?0:1;fallbackProvider.SelectedItem=settings.Models.FirstOrDefault(p=>p.IsCloud&&p.Id==conversation.FallbackProviderId)??settings.Models.FirstOrDefault(p=>p.IsCloud);chatHeading.Text=ProjectForChat() is {} headingProject?(headingProject.Name+" / "+(conversation.Title=="New conversation"?"New chat":conversation.Title)):(conversation.Title=="New conversation"?"":conversation.Title);chatHeading.ToolTip=conversation.Title;if(shownChat!=conversation.Id){shownChat=conversation.Id;RestoreDocument();prompt.Text=composerDrafts.TryGetValue(conversation.Id,out var promptDraft)?promptDraft:"";activeDraft=null;loadingEditor=true;codeEditor.Clear();codeEditor.IsReadOnly=true;loadingEditor=false;codeHeading.Text="Code workspace";codeHint.Text="Open a code block or select a source file.";ShowChat();}UpdateEditorActions();}finally{syncingUi=false;}}
    private void RenderWelcome(){var welcome=new StackPanel{MaxWidth=630,HorizontalAlignment=HorizontalAlignment.Center,Margin=new Thickness(20,90,20,20)};welcome.Children.Add(new TextBlock{Text="How can I help?",FontSize=30,FontWeight=FontWeights.SemiBold,TextAlignment=TextAlignment.Center,Foreground=Brush("#E6EBF5")});welcome.Children.Add(new TextBlock{Text="Ask a question or describe what you want to do.",FontSize=14,Foreground=Brush("#98A4B7"),TextAlignment=TextAlignment.Center,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,12,0,28)});var starters=new WrapPanel{MaxWidth=444,HorizontalAlignment=HorizontalAlignment.Center};welcome.Children.Add(starters);foreach(var (label,draft) in new[]{("Build a feature","Help me build a feature. First clarify the requirements, then propose complete code and checks."),("Explain some code","Explain the included code, its main flow and any important assumptions."),("Find and fix a bug","Help me diagnose a bug in the included files. Identify the cause and propose a reviewable fix."),("Research an approach","Help me research an approach. Identify what we need to verify and cite any included web sources.")}){var b=FlatButton(label,()=>{prompt.Text=draft;prompt.Focus();prompt.CaretIndex=prompt.Text.Length;});b.Tag="Starter: "+label;b.Width=210;b.Margin=new Thickness(6);b.Padding=new Thickness(12,10,12,10);b.Background=Brush("#252525");b.BorderBrush=Brush("#3A3A3A");starters.Children.Add(b);}transcript.Children.Add(welcome);scroll.ScrollToTop();}
    private void ShowChat(){returnToChat.Visibility=Visibility.Collapsed;LeaveAgentSurface();chatView.Visibility=Visibility.Visible;codeView.Visibility=Visibility.Collapsed;chatTab.Background=Brush("#232D43");codeTab.Background=Brush("#101318");}
    private void ShowCode(){returnToChat.Visibility=Visibility.Visible;LeaveAgentSurface();chatView.Visibility=Visibility.Collapsed;codeView.Visibility=Visibility.Visible;codeTab.Background=Brush("#232D43");chatTab.Background=Brush("#101318");}
    private void BuildCodeWorkspace(){var tools=new StackPanel{Margin=new Thickness(0,0,0,12)};DockPanel.SetDock(tools,Dock.Top);codeView.Children.Add(tools);tools.Children.Add(codeHeading);tools.Children.Add(codeHint);var actions=new WrapPanel();tools.Children.Add(actions);var copy=FlatButton("Copy",()=>{try{Clipboard.SetText(codeEditor.Text);status.Text="Draft copied.";}catch(System.Runtime.InteropServices.COMException){status.Text="Clipboard busy. Select and copy manually.";}});actions.Children.Add(copy);actions.Children.Add(editorDraft);actions.Children.Add(editorSave);editorDraft.Margin=new Thickness(0,0,6,0);editorDraft.Click+=(_,_)=>{if(activeDraft!=null){editorDrafts[activeDraft].Source=false;codeEditor.IsReadOnly=false;codeHint.Text="Editable draft • review the destination and changes before saving.";UpdateEditorActions();ShowCode();codeEditor.Focus();}};editorSave.Click+=(_,_)=>SaveEditorDraft();codeView.Children.Add(new Border{Background=Brush("#171B22"),BorderBrush=Brush("#2B3340"),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(8),Child=codeEditor});codeEditor.Background=Brush("#171B22");codeEditor.TextChanged+=(_,_)=>{if(loadingEditor||activeDraft==null)return;var d=editorDrafts[activeDraft];d.Text=codeEditor.Text;codeHint.Text=d.Text==d.Original?"Draft • review before saving":"Unsaved edits • review before saving";};}
    private void OpenCode(string text,string language,string? path,bool source){var key=conversation.Id+":"+(source?"source:":"draft:")+path+":"+Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text)));if(!editorDrafts.TryGetValue(key,out var draft))editorDrafts.Add(key,draft=new(text,language,path,source));activeDraft=key;loadingEditor=true;codeEditor.Text=draft.Text;codeEditor.IsReadOnly=draft.Source;loadingEditor=false;codeHeading.Text=draft.Path==null?"Generated "+(string.IsNullOrWhiteSpace(language)?"code":language.Trim()):Path.GetFileName(draft.Path);codeHeading.ToolTip=draft.Path;codeHint.Text=draft.Source?"Included source snapshot • make a draft to propose changes":draft.Text!=draft.Original?"Unsaved edits • review before saving":"Editable draft • review before saving";UpdateEditorActions();if(source)ShowDocument(text,path);else ShowCode();}
    private void UpdateEditorActions(){editorSave.IsEnabled=!busy&&activeDraft!=null&&!codeEditor.IsReadOnly;editorDraft.IsEnabled=!busy&&activeDraft!=null&&codeEditor.IsReadOnly;}
    private void SaveEditorDraft(){if(activeDraft==null||codeEditor.IsReadOnly||busy)return;var draft=editorDrafts[activeDraft];var window=new CodeSaveWindow(codeEditor.Text,draft.Language){Owner=this};if(saveTestAction!=null)window.Loaded+=(_,_)=>saveTestAction(window);if(window.ShowDialog()!=true||window.Receipt==null)return;var receipt=window.Receipt;savedCode[receipt.Path]=(codeEditor.Text,draft.Language);draft.Original=codeEditor.Text;draft.Path=receipt.Path;var previousKey=activeDraft;var savedKey=conversation.Id+":draft:"+receipt.Path+":"+Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(codeEditor.Text)));editorDrafts[savedKey]=draft;activeDraft=savedKey;if(previousKey.Contains(":source:",StringComparison.Ordinal))editorDrafts.Remove(previousKey);codeHeading.Text=Path.GetFileName(receipt.Path);codeHeading.ToolTip=receipt.Path;var notice=RecordSavedFile(receipt.Path,receipt,window.ReviewedPlan);codeHint.Text=notice+"Saved and verified • "+receipt.Path;status.Text=notice+"Saved and verified: "+receipt.Path+(receipt.BackupPath==null?"":" • Original backup: "+receipt.BackupPath);}
    private static IEnumerable<T> Descendants<T>(DependencyObject root) where T:DependencyObject{foreach(var child in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>()){if(child is T found)yield return found;foreach(var nested in Descendants<T>(child))yield return nested;}}
    private IEnumerable<Button> CodeButtons(string? tag=null)=>Descendants<Button>(transcript).Where(b=>tag==null||Equals(b.Tag,tag));
    private sealed class StatusSummary:IValueConverter{public object Convert(object value,Type targetType,object parameter,CultureInfo culture){var s=value as string??"Ready";return s.Split('•')[0].Trim();}public object ConvertBack(object value,Type targetType,object parameter,CultureInfo culture)=>Binding.DoNothing;}
